insert into public.assess_tests(key,title,intro,stop_after,sort,stop_mode) values ('spell','Spelling (graded, dictated words)','Listen to the word and the sentence. Type the word the way you think it is spelled.',8,8,'consec'),('fluency','One-minute reading','Read the story out loud. Start when I say go. Stop when I say stop.',999,9,'consec'),('pa_blend','Phonological awareness: blending sounds','Listen to the sounds, then say the word they make.',4,10,'consec'),('pa_seg','Phonological awareness: segmenting sounds','Listen to the word, then say each sound in the word, one at a time.',4,11,'consec'),('pa_elis','Phonological awareness: removing sounds','Listen to the word, then say it again without one part.',4,12,'consec'),('pa_iso','Phonological awareness: finding sounds','Listen to the word, then say the sound the teacher asks about.',4,13,'consec') on conflict (key) do update set title=excluded.title,intro=excluded.intro,stop_after=excluded.stop_after,sort=excluded.sort,stop_mode=excluded.stop_mode;
